(`entry`, `male_text`, `female_text`, `chat_type`, `sound_id`, `language_id`, `emote_id1`, `emote_id2`, `emote_id3`, `emote_delay1`, `emote_delay2`, `emote_delay3`)
VALUES
(269001, 'The body of the bronze soldier shatters as soon as you try to touch it.', 'The body of the bronze soldier shatters as soon as you try to touch it.', 2, 0, 0, 0, 0, 0, 0, 0, 0),
(269002, 'Please, I can''t handle this, end with my life...', 'Please, I can''t handle this, end with my life...', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(269003, 'AT LAST! Finally I can rest.', 'AT LAST! Finally I can rest.', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(269004, 'Careful... Careful with the drake. I just want to... sleep.', 'Careful... Careful with the drake. I just want to... sleep.', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(269005, 'This is suicide! End with my suffering, please, strangers...', 'This is suicide! End with my suffering, please, strangers...', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(269006, 'I can''t handle this suffering anymore...', 'I can''t handle this suffering anymore...', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(269007, 'Our numbers are endless!', 'Our numbers are endless!', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(269008, 'Our mission cannot be compromised!', 'Our mission cannot be compromised!', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(269009, 'You''re too late, we are infinite...', 'You''re too late, we are infinite...', 1, 0, 0, 0, 0, 0, 0, 0, 0),
(269010, 'Our numbers are endless!', 'Our numbers are endless!', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(269011, 'Our mission cannot be compromised!', 'Our mission cannot be compromised!', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(269012, 'You''re too late, we are infinite...', 'You''re too late, we are infinite...', 1, 0, 0, 0, 0, 0, 0, 0, 0),
(269013, 'The sands flow in our favor, we cannot be stopped!', 'The sands flow in our favor, we cannot be stopped!', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(269014, 'Our mission cannot be compromised! Stop them!', 'Our mission cannot be compromised! Stop them!', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(269015, 'You''re only delaying the inevitable... ', 'You''re only delaying the inevitable... ', 1, 0, 0, 0, 0, 0, 0, 0, 0),
(269016, 'Your pathetic magic means nothing!', 'Your pathetic magic means nothing!', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(269017, 'Our rifts must be preserved!', 'Our rifts must be preserved!', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(269018, 'Our time has come!', 'Our time has come!', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(269019, 'You''ve merely removed a grain from the hourglass... ', 'You''ve merely removed a grain from the hourglass... ', 1, 0, 0, 0, 0, 0, 0, 0, 0),
(269020, 'The timeways are ours to command!', 'The timeways are ours to command!', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(269021, 'The whelp begins vibrating with the energy it''s absorbed!', 'The whelp begins vibrating with the energy it''s absorbed!', 2, 0, 0, 0, 0, 0, 0, 0, 0),
(269022, 'The sands of time shall be scattered to the winds!', 'The sands of time shall be scattered to the winds!', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(269023, 'Impossible... ', 'Impossible... ', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(269024, 'Your courage fails!', 'Your courage fails!', 1, 0, 0, 0, 0, 0, 0, 0, 0),
(269025, 'It seems we have visitors. You should not have come here mortals, now I will ensure that you will not leave.', 'It seems we have visitors. You should not have come here mortals, now I will ensure that you will not leave.', 1, 0, 0, 0, 0, 0, 0, 0, 0),
(269026, 'Too soon...', 'Too soon...', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(269027, 'You''re nothing compared to my might!', 'You''re nothing compared to my might!', 1, 0, 0, 0, 0, 0, 0, 0, 0),
(269028, 'Your magic turns against you!', 'Your magic turns against you!', 1, 0, 0, 0, 0, 0, 0, 0, 0),
(269029, 'Enough playing around, this ends now!', 'Enough playing around, this ends now!', 1, 0, 0, 0, 0, 0, 0, 0, 0),
(269030, 'Shuul og i agthu yrr sk''uuyat uulwi ma oou sshoq''met ez nuq far''al I zz nuq al''tha Ssaggh ni za an''zig yrr puul ywaq gul''kafh', 'Shuul og i agthu yrr sk''uuyat uulwi ma oou sshoq''met ez nuq far''al I zz nuq al''tha Ssaggh ni za an''zig yrr puul ywaq gul''kafh', 1, 0, 0, 0, 0, 0, 0, 0, 0),
(269031, 'There is a great and terrible truth at the beginning of all things. I am its herald. Listen to my sermon, and know your infinite inconsequence.', 'There is a great and terrible truth at the beginning of all things. I am its herald. Listen to my sermon, and know your infinite inconsequence.', 5, 0, 0, 0, 0, 0, 0, 0, 0),
(269032, 'Hul bala miz rilakich...', 'Hul bala miz rilakich...', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(269033, 'How is this possible...', 'How is this possible...', 5, 0, 0, 0, 0, 0, 0, 0, 0),
(269034, 'W''oq uhn''agth ez qam Sk''arr!', 'W''oq uhn''agth ez qam Sk''arr!', 1, 0, 0, 0, 0, 0, 0, 0, 0),
(269035, 'Come, servants of rot.Consume!', 'Come, servants of rot.Consume!', 5, 0, 0, 0, 0, 0, 0, 0, 0),
(269036, 'Ak''agthshi ma uhnish, ak''uq shg''cul vwahuhn! H''iwn iggksh Phquathi gag OOU KAAXTH SHUUL!', 'Ak''agthshi ma uhnish, ak''uq shg''cul vwahuhn! H''iwn iggksh Phquathi gag OOU KAAXTH SHUUL!', 1, 0, 0, 0, 0, 0, 0, 0, 0),
(269037, 'Our numbers are endless, our power beyond reckoning! All who oppose the Destroyer will DIE A THOUSAND DEATHS!', 'Our numbers are endless, our power beyond reckoning! All who oppose the Destroyer will DIE A THOUSAND DEATHS!', 5, 0, 0, 0, 0, 0, 0, 0, 0),
(269038, 'Time moves in our favor, your intrusion ends here!', 'Time moves in our favor, your intrusion ends here!', 1, 0, 0, 0, 0, 0, 0, 0, 0),
(269039, 'We are infinite...', 'We are infinite...', 1, 0, 0, 0, 0, 0, 0, 0, 0),
(269040, 'Face the consequences of your actions!', 'Face the consequences of your actions!', 1, 0, 0, 0, 0, 0, 0, 0, 0),
(269041, 'Time for a change of pace!', 'Time for a change of pace!', 1, 0, 0, 0, 0, 0, 0, 0, 0),
(269042, '|cffff8040Rotmaw is consuming $n and cannot move!|r', '|cffff8040Rotmaw is consuming $n and cannot move!|r', 3, 0, 0, 0, 0, 0, 0, 0, 0),
(269043, 'Who dares defile the sanctity of the morass...', 'Who dares defile the sanctity of the morass...', 1, 0, 0, 0, 0, 0, 0, 0, 0),
(269044, 'You belong to the bog now...', 'You belong to the bog now...', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(269045, 'I failed...', 'I failed...', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(269046, 'The very earth rises in defiance...', 'The very earth rises in defiance...', 1, 0, 0, 0, 0, 0, 0, 0, 0),
(269047, '|cffff8040Mossheart covers $n with moss!|r', '|cffff8040Mossheart covers $n with moss!|r', 3, 0, 0, 0, 0, 0, 0, 0, 0),
(269048, 'You again?! So the others have failed to stop the lapdogs of the Bronze, pathetic. Know that I am not like them, I have spent centuries in a paradox to attain this form.', 'You again?! So the others have failed to stop the lapdogs of the Bronze, pathetic. Know that I am not like them, I have spent centuries in a paradox to attain this form.', 1, 0, 0, 0, 0, 0, 0, 0, 0),
(269049, 'We are Infinite!Your journey ends here now, time will belong to US!', 'We are Infinite!Your journey ends here now, time will belong to US!', 1, 0, 0, 0, 0, 0, 0, 0, 0),
(269050, 'My death changes nothing, YOU HEAR ME? NOTHING!', 'My death changes nothing, YOU HEAR ME? NOTHING!', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(269051, '|cffff8040Antnormi is preparing for a bellowing roar!|r', '|cffff8040Antnormi is preparing for a bellowing roar!|r', 3, 0, 0, 0, 0, 0, 0, 0, 0),
(269052, 'Let time undo you!', 'Let time undo you!', 1, 0, 0, 0, 0, 0, 0, 0, 0),
(269053, 'Let time undo you!', 'Let time undo you!', 1, 0, 0, 0, 0, 0, 0, 0, 0),
(269054, '%s goes into a frenzy!', '%s goes into a frenzy!', 3, 0, 0, 0, 0, 0, 0, 0, 0),
(269055, 'Echo of Gerastrasz prepares to sacrifice himself and heal the Commander.', 'Echo of Gerastrasz prepares to sacrifice himself and heal the Commander.', 2, 0, 0, 0, 0, 0, 0, 0, 0),
(269056, 'Echo of Gerastrasz begins to heal the Commander.', 'Echo of Gerastrasz begins to heal the Commander.', 2, 0, 0, 0, 0, 0, 0, 0, 0),
(269057, 'I am eternal!', 'I am eternal!', 1, 0, 0, 0, 0, 0, 0, 0, 0),
(269058, 'Who dares disrupt our majestic plan? The master won''t like this.', 'Who dares disrupt our majestic plan? The master won''t like this.', 1, 0, 0, 0, 0, 0, 0, 0, 0),
(269059, 'Already? So soon...', 'Already? So soon...', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(269060, 'BAH! USELESS MINION!', 'BAH! USELESS MINION!', 1, 0, 0, 0, 0, 0, 0, 0, 0),
